using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Binary.Streams;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Snap template and snap template node fields get xEdit's names and types (wbDefinitionsSF1 STMP, STND):
// - STMP BNAM is the Bound Override (xEdit: Vec3 Override -, Vec3 Override +): the 6-float array is renamed
//   BoundOverride (3 in Starfield.esm, 24 bytes).
// - STMP STPT is the Snap Piece Type enum (655, all 0 = Invalid); CNAM is the traversal category Name (17).
// - Each node (ENAM) ends with the UInt32 Display Case Slot and 4 unknown bytes (was one UInt64): 3,128 nodes, the
//   slot 0..11, the last 4 bytes always 0.
// - STND CNAM is the Color, FNAM the Flags (Snaps To Self, Is Hinge, Display Node, Run Behaviors When Not Snapped;
//   values 0, 1, 4, 8), SNST the Stairway Type enum (148, all 0 = None).
// Each test reads a whole record from Starfield.esm with both readers and writes it back byte for byte.
public class SnapTemplateFieldNameTests
{
    private static void WritesBack(Action<MutagenWriter> write, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(write));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    private static IEnumerable<ISnapTemplateGetter> Stmp(string hex)
        => ReadBoth<ISnapTemplateGetter>(Record("STMP", Hex(hex)), f => SnapTemplate.CreateFromBinary(f), (s, p) => SnapTemplateBinaryOverlay.SnapTemplateFactory(s, p));

    private static IEnumerable<ISnapTemplateNodeGetter> Stnd(string hex)
        => ReadBoth<ISnapTemplateNodeGetter>(Record("STND", Hex(hex)), f => SnapTemplateNode.CreateFromBinary(f), (s, p) => SnapTemplateNodeBinaryOverlay.SnapTemplateNodeFactory(s, p));

    // DisplaySnap_WeaponsCasePistol01 (1F63E7:Starfield.esm)
    private const string PistolCase = "";
    // TraversalLadderSnapTemplate (05163A:Starfield.esm)
    private const string Ladder = "";
    // DisplaySnap_WeaponRack03 (12F129:Starfield.esm)
    private const string WeaponRack = "";
    // SnapNode_DoorFrameSm01 (007E0B:Starfield.esm)
    private const string DoorFrame = "";
    // SnapNode_Display_AmmoBoxSmall01 (0A0D33:Starfield.esm)
    private const string AmmoBox = "";
    // SnapNode_STN_PlugSide01Window (1C1469:Starfield.esm)
    private const string PlugSide = "";

    [Fact]
    public void SnapTemplate_BoundOverride()
    {
        foreach (var stmp in Stmp(PistolCase))
        {
            var bounds = stmp.BoundOverride.ShouldNotBeNull().ToArray();
            bounds[0].ShouldBe(-0.6f, 0.0001f);
            bounds[2].ShouldBe(-0.6f, 0.0001f);
            bounds[4].ShouldBe(0.6f, 0.0001f);
            stmp.SnapPieceType.ShouldBe(SnapTemplate.SnapPieceTypeEnum.Invalid);
            WritesBack(w => stmp.WriteToBinary(w), PistolCase);
        }
    }

    [Fact]
    public void SnapTemplate_TraversalCategoryName()
    {
        foreach (var stmp in Stmp(Ladder))
        {
            stmp.TraversalCategoryName.ShouldBe("Ladder");
            stmp.BoundOverride.ShouldBeNull();
            WritesBack(w => stmp.WriteToBinary(w), Ladder);
        }
    }

    [Fact]
    public void SnapTemplate_NodeDisplayCaseSlot()
    {
        foreach (var stmp in Stmp(WeaponRack))
        {
            stmp.Nodes.Count.ShouldBe(19);
            stmp.Nodes[0].NodeID.ShouldBe(0x1Du);
            stmp.Nodes[0].DisplayCaseSlot.ShouldBe(8u);
            stmp.Nodes.Select(n => n.DisplayCaseSlot).Max().ShouldBe(11u);
            stmp.Nodes.ShouldAllBe(n => n.Unknown == 0);
            WritesBack(w => stmp.WriteToBinary(w), WeaponRack);
        }
    }

    [Fact]
    public void SnapTemplateNode_ColorFlagsStairway()
    {
        foreach (var stnd in Stnd(DoorFrame))
        {
            stnd.Color.ShouldNotBeNull().R.ShouldBe((byte)0xFF);
            stnd.Flags.ShouldBe(SnapTemplateNode.Flag.SnapsToSelf);
            stnd.StairwayType.ShouldBe(SnapTemplateNode.StairwayTypeEnum.None);
            WritesBack(w => stnd.WriteToBinary(w), DoorFrame);
        }
        foreach (var stnd in Stnd(AmmoBox))
        {
            stnd.Flags.ShouldBe(SnapTemplateNode.Flag.DisplayNode);
            WritesBack(w => stnd.WriteToBinary(w), AmmoBox);
        }
        foreach (var stnd in Stnd(PlugSide))
        {
            stnd.Flags.ShouldBe(SnapTemplateNode.Flag.RunBehaviorsWhenNotSnapped);
            stnd.Color.ShouldNotBeNull().A.ShouldBe((byte)0xFF);
            WritesBack(w => stnd.WriteToBinary(w), PlugSide);
        }
    }
}
